<script setup lang="ts">export type PermissionItem={id:string;label:string;permission?:string;disabled?:boolean};defineProps<{items:PermissionItem[];permissions?:string[]}>();const emit=defineEmits<{select:[id:string]}>()</script><template><nav class="vx-permission-menu" aria-label="Actions"><template v-for="item in items" :key="item.id"><button v-if="!item.permission||permissions?.includes(item.permission)" type="button" :disabled="item.disabled" @click="emit('select',item.id)">{{item.label}}</button></template></nav></template>
